"""Development assembler; generated bytes need no keystone to build/check."""
import re
from pathlib import Path
import midi_extra as M
import mute_roll as V
from keystone import Ks, KS_ARCH_ARM, KS_MODE_THUMB
from capstone import Cs, CS_ARCH_ARM, CS_MODE_THUMB, CS_MODE_MCLASS

at, addresses, bodies = M.START, {}, {}
for name in M.ORDER:
    source = M.listing(name, addresses.get('SAFE', 0))
    code = bytearray(Ks(KS_ARCH_ARM, KS_MODE_THUMB).asm('.arch armv7e-m\n' + source, at)[0])
    instrs, _ = M.parse(source)
    decoded = list(Cs(CS_ARCH_ARM, CS_MODE_THUMB | CS_MODE_MCLASS).disasm(bytes(code), at, len(instrs)))
    for (_, mnemonic, operands), ins in zip(instrs, decoded):
        if mnemonic in ('bl', 'b.w') and operands.startswith('0x'):
            code[ins.address-at:ins.address-at+4] = M.branch(ins.address, int(operands, 16), mnemonic == 'bl')
    V.SOURCE['MIDI_' + name] = source
    assert not V.check_branches('MIDI_' + name, at, bytes(code)), V.check_branches('MIDI_' + name, at, bytes(code))
    addresses[name], bodies[name] = at, bytes(code)
    print(name, hex(at), len(code))
    at = (at + len(code) + 3) & ~3
path = Path(__file__).with_name('midi_extra.py')
text = path.read_text()
generated = '# GENERATED\nADDRESS = ' + repr(addresses) + '\nBODY = {\n'
generated += ''.join(f"    {n!r}: bytes.fromhex('{c.hex()}'),\n" for n,c in bodies.items())
generated += '}\n# END GENERATED'
path.write_text(re.sub(r'# GENERATED.*?# END GENERATED', lambda _: generated, text, flags=re.S), newline='\n')
